class Node{int v;Node left,right;Node(int v){this.v=v;}}class Main{static Node insert(Node root,int v){if(root==null)return new Node(v);if(v<root.v)root.left=insert(root.left,v);else root.right=insert(root.right,v);return root;}static void inorder(Node root){if(root!=null){inorder(root.left);System.out.print(root.v+" ");inorder(root.right);}}public static void main(String[] args){Node root=null;for(int v:new int[]{5,3,7,2,4})root=insert(root,v);inorder(root);}}
